var ENTERPRISE_COLLECTIONS = [
  "payment_requests",
  "fuel_payments",
  "cashbook",
  "trip_logs",
  "clients",
  "transport_crm_customers",
  "driver_applications",
  "todos",
  "credit_cards",
  "fuel_tracker",
  "fuel_stations",
  "trucks",
  "truck_docs",
  "employees",
  "employee_docs",
  "payroll",
  "company_settings",
  "company_vault_docs",
  "insurance_policies",
  "quotes",
  "maintenance_logs",
  "maintenance_problems",
  "parts_inventory"
];
async function exportEnterpriseBackupJSON() {
  const toastId = toast.loading("Exporting enterprise database backup (including payment requests & collections)...");
  try {
    const backupData = {
      version: "2.0",
      exported_at: (/* @__PURE__ */ new Date()).toISOString(),
      platform: "Jai Bhavani Cargo Enterprise ERP",
      collections: {}
    };
    let totalRecordCount = 0;
    for (const colName of ENTERPRISE_COLLECTIONS) {
      try {
        const records = await pocketbaseClient_default.collection(colName).getFullList({ $autoCancel: false }).catch(() => []);
        backupData.collections[colName] = records || [];
        totalRecordCount += (records || []).length;
      } catch (err2) {
        console.warn(`Could not export collection ${colName}:`, err2);
        backupData.collections[colName] = [];
      }
    }
    const jsonString = JSON.stringify(backupData, null, 2);
    const blob = new Blob([jsonString], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const timestamp = format(/* @__PURE__ */ new Date(), "yyyy-MM-dd_HH-mm");
    const a4 = document.createElement("a");
    a4.href = url;
    a4.download = `JaiBhavaniCargo_FULL_BACKUP_INCL_PAYMENTS_${timestamp}.json`;
    document.body.appendChild(a4);
    a4.click();
    document.body.removeChild(a4);
    URL.revokeObjectURL(url);
    toast.success(`Enterprise backup downloaded! (${totalRecordCount} records across ${Object.keys(backupData.collections).length} collections)`, { id: toastId });
    return backupData;
  } catch (err2) {
    console.error("Failed to export enterprise backup:", err2);
    toast.error("Failed to export enterprise database backup.", { id: toastId });
    throw err2;
  }
}

